std::vector<Vertex> verts;std::vector<GLuint> indices;std::vector<Instance> instances;Mesh meshes[9];Command commands[5];GLuint textures[8],vao,vbo,ebo,screenVAO,instanceBuffer,visibleBuffer,indirectBuffer,lightsBuffer,geo,lightProg,post,cull,reduce;GLuint shadowF,shadowTex;mat4 shadowVP[3];bool normalOn=true,shadows=true,occlusion=true,fireflies=true,bloom=true,cascadeColor=false,depthDebug=false;int debug=0,mip=0;int lightCount=0;
